            parser.error("port out of range")
        if not os.path.isabs(args.model) or not os.path.isdir(args.model):
            parser.error("model must be an absolute directory")
        return args


    def read_token(path):
        with open(path, "r", encoding="ascii") as handle:
            token = handle.read().strip()
        if len(token) != 64 or any(c not in "0123456789abcdef" for c in token):
            raise SystemExit("launcher: the token file must hold 64 lowercase hex digits")
        return token.encode()


    def authenticating(handler_class, token):
        """Wrap every request method with the bearer check."""

        class Authenticated(handler_class):
            def _authorized(self):
                if self.headers.get("Origin") is not None:
                    return False
                values = self.headers.get_all("Authorization") or []
                if len(values) != 1 or not values[0].startswith("Bearer "):
                    return False
                return hmac.compare_digest(values[0][7:].encode(), token)

            def _refuse(self):
                self.send_response(401)
                self.send_header("Content-Length", "0")
                self.send_header("Connection", "close")
                self.end_headers()
                self.close_connection = True

            def _set_cors_headers(self):
                pass

            def do_POST(self):
                if not self._authorized():
                    return self._refuse()
                return super().do_POST()

            def _challenge(self, nonce):
                if self.headers.get("Origin") is not None:
                    return self._refuse()
                body = hmac.new(token, nonce.encode(), hashlib.sha256).hexdigest().encode()
                self.send_response(200)
                self.send_header("Content-Type", "text/plain")
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Connection", "close")
                self.end_headers()
                self.wfile.write(body)
                self.close_connection = True

            def do_GET(self):
                challenge = CHALLENGE.match(self.path)
                if challenge:
                    return self._challenge(challenge.group(1))
                if not self._authorized():
                    return self._refuse()
                return super().do_GET()

            def do_OPTIONS(self):
                return self._refuse()

            def log_message(self, *args):
                # Request lines can carry prompt fragments; log nothing.
                pass

        return Authenticated


